function contractDoc(c){const row=(a,b,x,y)=>'<tr><th>'+a+'</th><td>'+E(b||'—')+'</td><th>'+x+'</th><td>'+E(y||'—')+'</td></tr>';const sig=side=>{const s=c.signatures?.[side];return '<div><strong>'+(side==='employer'?'الطرف الأول — الشركة':'الطرف الثاني — الموظف')+'</strong>'+signatureSvg(s)+'<div>'+E(s?.name||'الاسم والتوقيع: .....................')+'</div><small>'+E(s?.at?stamp(s.at)+' · '+new Date(s.at).toLocaleTimeString('en-GB'):'التاريخ: .....................')+'</small></div>';};return '<article class="m14-preview"><header><div><b>'+E(c.company)+'</b><h1>عقد '+E(c.type==='مستقل / فريلانس'?'تعاون مستقل':'توظيف')+'</h1></div><div><bdi>'+E(c.number)+'</bdi><br>'+E(contractStatus(c))+' · نسخة '+E(c.version||1)+'</div></header><h2>أولًا: أطراف العقد</h2><p>الطرف الأول: '+E(c.company)+'، ممثلًا بـ '+E(c.companyRepresentative||'........................')+'، وعنوانه '+E(c.companyAddress||'........................')+'.\nالطرف الثاني: '+E(c.employeeName)+'، رقم الموظف '+E(c.employeeNo)+'، رقم الهوية / الجواز '+E(c.nationalId||'........................')+'، وعنوانه '+E(c.employeeAddress||'........................')+'.</p><h2>ثانيًا: بيانات العمل المتفق عليها</h2><table>'+row('القسم',c.department,'المسمى',c.jobTitle)+row('نوع العقد',c.type,'طبيعة العمل',c.workMode)+row('البداية',stamp(c.startDate),'النهاية',c.endDate?stamp(c.endDate):'غير محددة')+row('نوع التوظيف',c.employmentType,'التجربة',c.probationMonths+' شهر')+row('الأجر',c.salary+' '+c.currency,'الدورية',c.payCycle)+row('ساعات اليوم',c.workHours,'أيام الأسبوع',c.weeklyDays)+row('الإجازة السنوية',c.annualLeave+' يوم','الموقع',c.workLocation)+'</table><h2>ثالثًا: المهام والمسؤوليات</h2>'+(window.MoshUI15?MoshUI15.contracts.document(c,'duty'):'<p>'+E(c.duties||'تُستكمل قبل التوقيع.')+'</p>')+'<h2>رابعًا: الشروط والسياسات المتفق عليها</h2>'+(window.MoshUI15?MoshUI15.contracts.document(c,'condition'):'<p>'+E(c.terms||'تُستكمل قبل التوقيع.')+'</p>')+'<h2>خامسًا: البدلات والمزايا</h2><p>'+E(c.benefits||'لم تُذكر مزايا إضافية في هذه المسودة.')+'</p><h2>سادسًا: الإخطار وإنهاء العلاقة</h2><p>'+E(c.noticeTerms||'تُستكمل الشروط قبل اعتماد العقد.')+'</p>'+(c.notes?'<h2>ملاحظات إضافية</h2><p>'+E(c.notes)+'</p>':'')+'<p>بلد العمل / جهة الاختصاص للمراجعة: '+E(c.jurisdiction||'غير محددة')+'</p><h2>التوقيع</h2><div class="m14-contract-signs">'+sig('employer')+sig('employee')+'</div><p style="font-size:10px;color:#555;margin-top:20px">أُعدّ هذا المستند من MOSH ERP. التوقيعات المرسومة مسجلة ضمن النظام المحلي وليست تحققًا مستقلًا من هوية الأطراف. تُراجع المسودة وشروطها قبل اعتمادها.</p></article>';}
function previewContract(id=''){if(id)C=clone(A(state.employeeContracts).find(c=>c.id===id));else collectContract();if(!C)return;modal('معاينة عقد الموظف',contractDoc(C),btn('طباعة / حفظ PDF','contract-print','','primary')+btn('رجوع للعقد','contract-back'),true);}
function printContract(){if(!C)return;const f=document.createElement('iframe');f.style.cssText='position:fixed;width:1px;height:1px;right:0;bottom:0;border:0;';f.title='نسخة العقد للطباعة';document.body.append(f);const css='.m14-preview,.m14-preview *{color:#000!important;-webkit-text-fill-color:#000!important;text-shadow:none!important}.m14-preview th,.m14-preview td{background:#fff!important}.m14-preview h3{font-size:13px;break-after:avoid}body{margin:0;font-family:Arial,sans-serif;color:#000}*{box-sizing:border-box}.m14-preview{padding:0;font-size:12px;line-height:1.85}.m14-preview h1{font-size:21px}.m14-preview h2{font-size:15px;border-bottom:1px solid #aaa;margin-top:18px;break-after:avoid}.m14-preview p{white-space:pre-wrap}.m14-preview table{width:100%;border-collapse:collapse;font-size:11px}.m14-preview th,.m14-preview td{border:1px solid #bbb;padding:6px;text-align:right}.m14-preview header{display:flex;justify-content:space-between}.m14-contract-signs{display:flex;gap:40px;break-inside:avoid}.m14-contract-signs>div{width:50%}.m14-sign-svg{width:100%;height:75px}tr{break-inside:avoid}@page{size:A4;margin:16mm 15mm}';const paper=(window.MoshStationery?.wrap?window.MoshStationery.wrap(contractDoc(C),'عقد موظف'):contractDoc(C)),stationeryCss=window.MoshStationery?.printCss||'';f.srcdoc='<!doctype html><html lang="ar" dir="rtl"><head><meta charset="utf-8"><title>'+E(C.number)+'</title><style>'+css+stationeryCss+'</style></head><body>'+paper+'</body></html>';f.onload=()=>{setTimeout(()=>{try{f.contentWindow.focus();f.contentWindow.print();}catch(e){toast('افتح التطبيق بمتصفح خارجي للطباعة ثم اختر حفظ PDF.',true);}setTimeout(()=>f.remove(),60000);},150);};}
function signatureDialog(id){C=clone(A(state.employeeContracts).find(c=>c.id===id));if(!C)return;if(C.status==='archived'){toast('العقد مؤرشف.',true);return;}if(!C.duties||!C.terms||!C.noticeTerms){toast('أكمل المهام وشروط الشركة وشروط الإخطار قبل تسجيل التوقيع.',true);editContract(C.id);return;}signSide=C.signatures?.employer?'employee':'employer';signStrokes=[];modal('تسجيل توقيع على العقد','<div class="m14-note info">'+E(C.number+' — '+C.employeeName)+'<br>بمجرد حفظ أول توقيع يُقفل نص العقد. أي تغيير لاحق يتطلب نسخة جديدة وتوقيعًا جديدًا.</div><div class="m14-grid">'+select('الطرف الموقع','m14SignSide',[['employer','ممثل الشركة'],['employee','الموظف']],signSide)+input('اسم صاحب التوقيع','m14SignName',signSide==='employee'?C.employeeName:C.companyRepresentative)+'</div><div class="m14-sign-box" style="margin-top:15px"><canvas id="m14SignCanvas" width="600" height="180" aria-label="ارسم التوقيع هنا"></canvas><div class="m14-actions">'+btn('مسح الرسم','sign-clear')+'</div></div><label><input type="checkbox" id="m14SignConsent"> أؤكد الاطلاع على العقد وأن هذا توقيع الطرف المحدد.</label><small style="display:block">هذا تسجيل محلي؛ لا يتحقق النظام من هوية الموقّع.</small>',btn('حفظ التوقيع','sign-save','','primary'),true);const c=Q('m14SignCanvas'),ctx=c.getContext('2d');let line=null;ctx.strokeStyle='#172126';ctx.lineWidth=2.5;ctx.lineCap='round';const point=e=>{const b=c.getBoundingClientRect();return [Math.max(0,Math.min(600,(e.clientX-b.left)*600/b.width)),Math.max(0,Math.min(180,(e.clientY-b.top)*180/b.height))];};c.onpointerdown=e=>{c.setPointerCapture(e.pointerId);line=[point(e)];signStrokes.push(line);ctx.beginPath();ctx.moveTo(...line[0]);};c.onpointermove=e=>{if(!line)return;const p=point(e);line.push(p);ctx.lineTo(...p);ctx.stroke();};c.onpointerup=c.onpointercancel=()=>line=null;Q('m14SignSide').onchange=()=>{signSide=value('m14SignSide');Q('m14SignName').value=signSide==='employee'?C.employeeName:C.companyRepresentative;signStrokes=[];ctx.clearRect(0,0,600,180);};}
async function saveSignature(){if(!permitted())return;if(!value('m14SignName')||!Q('m14SignConsent')?.checked||signStrokes.reduce((n,l)=>n+l.length,0)<3){toast('أدخل اسم الموقّع وارسم التوقيع ثم أكد الاطلاع.',true);return;}const side=value('m14SignSide'),stored=A(state.employeeContracts).find(c=>c.id===C.id);if(!stored||stored.status==='archived'||stored.signatures?.[side]){toast('هذا الطرف وقّع سابقًا أو العقد غير متاح. لا يُستبدل توقيع محفوظ.',true);return;}const sig={name:value('m14SignName'),at:now(),recordedBy:name(),strokes:clone(signStrokes)};const ok=await transaction(()=>{stored.signatures=stored.signatures||{};stored.signatures[side]=sig;stored.status=stored.signatures.employer&&stored.signatures.employee?'signed':'pending_signature';stored.updatedAt=now();const p=getStaffProfileById(stored.employeeId);p.auditTrail=A(p.auditTrail);p.auditTrail.push({time:now(),by:name(),text:'تسجيل توقيع '+(side==='employee'?'الموظف':'ممثل الشركة')+' على العقد '+stored.number});},'تم حفظ التوقيع وقفل نص العقد.');if(ok)previewContract(stored.id);}
async function removeContract(id){if(!permitted())return;const c=A(state.employeeContracts).find(x=>x.id===id);if(!c)return;const signed=Object.keys(c.signatures||{}).length>0;if(!await ask(signed?'أرشفة العقد الموقّع مع الاحتفاظ بالتوقيعات والنسخة؟':'حذف مسودة العقد '+c.number+'؟'))return;const ok=await transaction(()=>{if(signed)c.status='archived';else state.employeeContracts=state.employeeContracts.filter(x=>x.id!==id);},signed?'تمت أرشفة العقد دون حذف التوقيعات.':'تم حذف مسودة العقد.');if(ok)contracts(c.employeeId);}
function copyContract(id){const c=A(state.employeeContracts).find(x=>x.id===id);if(!c)return;C=clone(c);C.id=uid('HRC');C.number=c.number+'-V'+(num(c.version,1)+1)+'-'+String(Date.now()).slice(-4);C.parentContractId=c.id;C.version=num(c.version,1)+1;C.signatures={};C.status='draft';C.createdAt=now();C.createdBy=name();editContract();}
let evalContext=null;
function evalEdit(arg){if(!permitted())return;const [pid,id]=arg.split('|'),p=getStaffProfileById(pid),r=A(p?.evaluationRecords).find(x=>String(x.id)===id);if(!r)return;evalContext={pid,id};modal('تعديل تقييم الموظف','<div class="m14-grid">'+input('تاريخ التقييم','m14EvalDate',r.date||today(),'date')+input('النتيجة من 100','m14EvalScore',r.score??r.rating??'','number','min="0" max="100"')+textArea('ملاحظات التقييم','m14EvalNote',r.note||r.notes||'')+'</div>',btn('حفظ وإغلاق','eval-save','','primary'));}
async function evalSave(){if(!evalContext||!dateValid(Q('m14Modal')))return;const {pid,id}=evalContext,p=getStaffProfileById(pid),r=A(p?.evaluationRecords).find(x=>String(x.id)===id),score=value('m14EvalScore');if(!r||score===''||num(score,-1)<0||num(score)>100||!iso(value('m14EvalDate'))){toast('تحقق من التاريخ والنتيجة بين 0 و100.',true);return;}const ok=await transaction(()=>Object.assign(r,{date:value('m14EvalDate'),score:num(score),note:value('m14EvalNote'),updatedAt:now(),updatedBy:name()}));if(ok){if(S?.id===pid)S.base.evaluationRecords=clone(p.evaluationRecords);closeModal();pane('performance',perfHtml(p));}}
