window.openStaffDocument=async function(key,filename='',download=false){try{const r=await getAttachmentRecord(key);if(!r?.blob)throw Error('المرفق غير موجود في هذا المتصفح');if(download)return fileDownload(r.blob,filename||r.name);const url=URL.createObjectURL(r.blob),a=document.createElement('a');a.href=url;a.target='_blank';a.rel='noopener';document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),60000);}catch(e){toast('تعذر الوصول للمرفق: '+e.message,true);}};
function fileDownload(blob,filename){const url=URL.createObjectURL(blob);modal('تحميل الوثيقة','<p>الملف جاهز. اضغط على الرابط أدناه لحفظه على جهازك.</p><div class="m14-actions"><a class="btn primary" href="'+url+'" download="'+E(filename||'document')+'">تحميل '+E(filename||'الوثيقة')+'</a><a class="btn" href="'+url+'" target="_blank" rel="noopener">فتح الملف للحفظ من المتصفح</a></div><p class="m14-footer-note">إن منعت معاينة المحادثة التنزيل، افتح ملف التطبيق مباشرة في المتصفح. لا تحذف بيانات المتصفح لأن الملفات محفوظة فيه.</p>');setTimeout(()=>URL.revokeObjectURL(url),180000);}
window.deleteStaffDocument=async function(pid,id){if(!permitted())return;const p=getStaffProfileById(pid),r=A(p?.documents).find(x=>String(x.id)===String(id));if(!p||!r||!await ask('حذف الوثيقة «'+(r.title||r.name)+'» من ملف الموظف؟'))return;const ok=await transaction(()=>{p.documents=p.documents.filter(x=>String(x.id)!==String(id));p.auditTrail=A(p.auditTrail);p.auditTrail.push({time:now(),by:name(),text:'حذف وثيقة '+(r.title||r.name)});},'تم حذف بيانات الوثيقة.');if(ok){if(typeof MoshStaffDocs13A?.reset==='function')MoshStaffDocs13A.reset();openStaffEmployeeForm(pid);setTimeout(()=>switchHrEmployeeTab('documents'),100);}};
