const oldApplyRequest14=window.hrProApplyRequest;
window.hrProApplyRequest=function(r){const result=oldApplyRequest14.apply(this,arguments);if(r.type==='hourly_leave'){const p=getStaffProfileById(r.employeeId);if(p&&!A(p.leaveRecords).some(x=>String(x.id)===String(r.id))){p.leaveRecords=A(p.leaveRecords);p.leaveRecords.push({id:r.id,type:'ساعية',startDate:r.data.date,endDate:r.data.date,fromTime:r.data.fromTime,toTime:r.data.toTime,hours:round(hrCalculateAttendanceHours(r.data.fromTime,r.data.toTime,0)),workdayHours:Math.max(1,num(state.hrProSettings?.workdayHours,8)),deductAnnual:false,days:0,status:'approved',note:r.reason||'',createdAt:r.createdAt,createdBy:r.createdBy});}}return result;};
const originalDisciplinary=window.hrDisciplinaryPaneHtml;window.hrDisciplinaryPaneHtml=function(p){let s=originalDisciplinary(p);if(!p)return s;const box=document.createElement('div');box.innerHTML=s;box.querySelectorAll('button[onclick^="hrDeleteDisciplinary"]').forEach(b=>{const m=b.getAttribute('onclick').match(/'([^']+)'/g);if(m?.length>=2)b.insertAdjacentHTML('beforebegin',btn('تعديل','disc-edit',p.id+'|'+m[1].slice(1,-1)));});return box.innerHTML;};
// Event delegation remains in one place; actions never depend on native confirm dialogs.
document.addEventListener('click',async e=>{const b=e.target.closest('[data-m14]');if(!b)return;e.preventDefault();const act=b.dataset.m14,arg=b.dataset.arg||'';try{
 if(act==='close')closeModal();
 else if(act==='asset-add'){collectAssets();S.assets.push({id:uid('ASSET'),type:'لاب توب',name:'',serial:'',issuedDate:'',status:'مسلمة',notes:''});mark('assets');Q('m14Assets').innerHTML=assetHtml();dates(Q('m14Assets'));}
 else if(act==='asset-remove'){collectAssets();if(await ask('حذف هذه العهدة من قائمة الموظف؟ يعتمد التغيير عند حفظ الملف.')){S.assets.splice(num(arg),1);mark('assets');Q('m14Assets').innerHTML=assetHtml();}}
 else if(act==='leave-policy'){S.annual=Math.max(0,num(value('m14Annual')));S.cycle=value('m14Cycle');S.opening=num(value('m14Opening'));mark('leave');pane('leave',leaveHtml(S.base));}
 else if(act==='leave-form')leaveForm();
 else if(act==='leave-edit'){const r=S.leave.find(x=>x.id===arg);if(linked(r))toast('التعديل على سجل مرتبط بموافقة يتم من طلبه الأصلي.',true);else leaveForm(arg);}
 else if(act==='leave-stage')stageLeave();
 else if(act==='leave-remove')await removeRecord('leave',arg);
 else if(act==='att-form')attendanceForm();
 else if(act==='att-edit'){const r=S.attendance.find(x=>x.id===arg);if(linked(r))toast('هذا تصحيح دوام معتمد من طلب. افتح طلب التصحيح لتعديل المسار.',true);else attendanceForm(arg);}
 else if(act==='att-stage')stageAttendance();
 else if(act==='att-remove')await removeRecord('attendance',arg);
 else if(act==='record-cancel'){Q(arg==='leave'?'m14LeaveForm':'m14AttForm').innerHTML='';}
 else if(act==='task'){closeModal();goApp('tasks');openTaskDetailsFromAll(arg);}
 else if(act==='employee-edit')openStaffEmployeeForm(arg);
 else if(act==='employee-remove')await deleteEmployee(arg);
 else if(act==='contracts')contracts(arg);
 else if(act==='contract-new')await newContract(arg);
 else if(act==='contract-select'){const id=value('m14ContractEmployee');if(!id)toast('اختر الموظف.',true);else await newContract(id);}
 else if(act==='contract-edit')editContract(arg);
 else if(act==='contract-save')await saveContract();
 else if(act==='contract-preview')previewContract(arg);
 else if(act==='contract-preview-draft'){collectContract();previewContract();}
 else if(act==='contract-back')editContract();
 else if(act==='contract-print')printContract();
 else if(act==='contract-copy')copyContract(arg);
 else if(act==='contract-remove')await removeContract(arg);
 else if(act==='contract-sign')signatureDialog(arg);
 else if(act==='sign-clear'){signStrokes=[];Q('m14SignCanvas').getContext('2d').clearRect(0,0,600,180);}
 else if(act==='sign-save')await saveSignature();
 else if(act==='eval-edit')evalEdit(arg);
 else if(act==='eval-save')await evalSave();
 else if(act==='eval-remove')await evalRemove(arg);
 else if(act==='disc-edit'){const [pid,id]=arg.split('|');discEdit(pid,id);}
 else if(act==='disc-save')await saveDisc();
 }catch(err){console.error('MOSH HR14 action',act,err);toast('تعذر تنفيذ الإجراء. لم يظهر تأكيد حفظ. '+String(err.message||err),true);}});
